UPDATE tianquan_oauth.oauth_signing_key
SET status = #{po.status}, activated_at = #{po.activatedAt}, last_issued_at = #{po.lastIssuedAt},
    verify_until = #{po.verifyUntil}, retired_at = #{po.retiredAt}, version = #{po.version},
    update_user_id = #{po.updateUserId}, update_time = #{po.updateTime}
WHERE tenant_id = #{tenantId} AND id = #{po.id} AND kid = #{po.kid}
  AND algorithm = #{po.algorithm} AND version = #{expectedVersion} AND deleted_at IS NULL

UPDATE tianquan_oauth.oauth_signing_key
SET deleted_at = CURRENT_TIMESTAMP AT TIME ZONE 'UTC', version = version + 1,
    update_user_id = #{po.updateUserId}, update_time = #{po.updateTime}
WHERE tenant_id = #{tenantId} AND id = #{po.id}
  AND version = #{expectedVersion} AND deleted_at IS NULL
